def roman_to_int(s: str) -> int:
    roman_map = {
        'M': 1000, 'D': 500, 'C': 100, 'L': 50, 'X': 10, 'V': 5, 'I': 1
    }
    int_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    result = 0
    for char in s:
        result += int_map[char]
        if char in roman_map:
            result -= roman_map[char]
    return result
